// MK-10: real terrain skylines for ANY point near the south pole, computed in the browser.
// Uses window.MW_TERRAIN_GRID (generated by tools/make_horizons.py from NASA LOLA topography:
// 240 m cells from 84S to the pole for nearby terrain, 960 m cells from 75S for distant mountains)
// and the same method as the Python tool: for every 0.5 deg of
// azimuth, march outward over the curved Moon and keep the highest terrain angle seen from
// an observer standing mastM above the ground.
// Works in the browser (window.MoonTerrain) and in Node (module.exports) for the unit tests.
// Code generated with an AI assistant (Claude) from our team's requirements.
(function (root) {
  'use strict';
  const D2R = Math.PI / 180, R2D = 180 / Math.PI;

  function base64ToBytes(b64) {
    if (typeof Buffer !== 'undefined') return new Uint8Array(Buffer.from(b64, 'base64'));
    const bin = atob(b64), out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  // raw = inflated bytes: n*n low bytes then n*n high bytes of zig-zag residuals.
  function decodeHeights(raw, n, q) {
    const N = n * n, Z = new Float32Array(N);
    const zi = new Int32Array(N);
    for (let i = 0; i < N; i++) {
      const u = raw[i] | (raw[N + i] << 8);
      const r = (u >>> 1) ^ -(u & 1);
      const row = (i / n) | 0, col = i - row * n;
      let pred;
      if (row === 0) pred = col === 0 ? 0 : zi[i - 1];
      else if (col === 0) pred = zi[i - n];
      else pred = zi[i - 1] + zi[i - n] - zi[i - n - 1];
      zi[i] = pred + r;
      Z[i] = zi[i] * q;
    }
    return Z;
  }

  // Browser: inflate with the built-in DecompressionStream ('deflate' = zlib format).
  async function inflateBrowser(b64) {
    const stream = new Blob([base64ToBytes(b64)]).stream().pipeThrough(new DecompressionStream('deflate'));
    return new Uint8Array(await new Response(stream).arrayBuffer());
  }
  async function loadBrowser(meta) {
    const [near, far] = await Promise.all([inflateBrowser(meta.near.data), inflateBrowser(meta.far.data)]);
    return create(meta, decodeHeights(near, meta.near.size, meta.quantM), decodeHeights(far, meta.far.size, meta.quantM));
  }

  // Node: pass require('zlib').inflateSync.
  function loadNode(meta, inflateSync) {
    const raw = g => new Uint8Array(inflateSync(Buffer.from(g.data, 'base64')));
    return create(meta, decodeHeights(raw(meta.near), meta.near.size, meta.quantM), decodeHeights(raw(meta.far), meta.far.size, meta.quantM));
  }

  function grid(g, Z) {
    const n = g.size, cell = g.cellM, half = n * cell / 2;
    return function (x, y) {
      const c = (x + half) / cell - 0.5, r = (half - y) / cell - 0.5;
      const c0 = Math.floor(c), r0 = Math.floor(r);
      if (c0 < 0 || r0 < 0 || c0 >= n - 1 || r0 >= n - 1) return NaN;
      const fc = c - c0, fr = r - r0, i = r0 * n + c0;
      return Z[i] * (1 - fc) * (1 - fr) + Z[i + 1] * fc * (1 - fr) + Z[i + n] * (1 - fc) * fr + Z[i + n + 1] * fc * fr;
    };
  }

  function create(meta, Znear, Zfar) {
    const R = meta.radiusM;
    const [sx, sy] = meta.convention;
    const step = meta.azStepDeg, A = Math.round(360 / step);
    const nearH = grid(meta.near, Znear), farH = grid(meta.far, Zfar);
    // Height: the 240 m grid wherever it covers, the 960 m grid beyond.
    const hXY = (x, y) => { const h = nearH(x, y); return Number.isFinite(h) ? h : farH(x, y); };
    // Distances along the ground: half-cell steps of the near grid to 20 km, then geometric to 400 km.
    const dist = [];
    for (let d = meta.near.cellM / 2; d < 20000; d += meta.near.cellM / 2) dist.push(d);
    for (let k = 0; k < 150; k++) dist.push(20000 * Math.pow(400000 / 20000, k / 149));
    const cosT = dist.map(d => Math.cos(d / R)), sinT = dist.map(d => Math.sin(d / R));
    // Unit vector P on the sphere -> south polar stereographic x, y (true scale at the pole).
    const projX = (px, py, pz) => sx * 2 * R * py / (1 - pz);
    const projY = (px, py, pz) => sy * 2 * R * px / (1 - pz);

    function frame(lat, lon) {
      const la = lat * D2R, lo = lon * D2R;
      return {
        up: [Math.cos(la) * Math.cos(lo), Math.cos(la) * Math.sin(lo), Math.sin(la)],
        east: [-Math.sin(lo), Math.cos(lo), 0],
        north: [-Math.sin(la) * Math.cos(lo), -Math.sin(la) * Math.sin(lo), Math.cos(la)]
      };
    }

    function heightAt(lat, lon) {
      const { up } = frame(lat, lon);
      return hXY(projX(...up), projY(...up));
    }

    const covers = lat => lat <= meta.siteLatLimit;
    // Grid detail at a point: 240 where the near grid covers it, else 960.
    const resAt = (lat, lon) => { const { up } = frame(lat, lon); return Number.isFinite(nearH(projX(...up), projY(...up))) ? meta.near.cellM : meta.far.cellM; };

    // Skyline: array of A elevation angles (deg), one per azStep starting at north, clockwise.
    function profile(lat, lon) {
      const { up, east, north } = frame(lat, lon);
      const h0 = hXY(projX(...up), projY(...up));
      if (!Number.isFinite(h0)) return null;
      const r0 = R + h0 + meta.mastM;
      const out = new Array(A);
      for (let a = 0; a < A; a++) {
        const az = a * step * D2R, ca = Math.cos(az), sa = Math.sin(az);
        const dx = ca * north[0] + sa * east[0], dy = ca * north[1] + sa * east[1], dz = ca * north[2] + sa * east[2];
        let best = -90;
        for (let k = 0; k < dist.length; k++) {
          const c = cosT[k], s = sinT[k];
          const px = c * up[0] + s * dx, py = c * up[1] + s * dy, pz = c * up[2] + s * dz;
          const h = hXY(projX(px, py, pz), projY(px, py, pz));
          if (!Number.isFinite(h)) continue;
          const r = R + h;
          const e = Math.atan2(r * c - r0, r * s) * R2D;
          if (e > best) best = e;
        }
        out[a] = Math.round(best * 100) / 100;
      }
      return { values: out, groundM: h0 };
    }

    return { profile, heightAt, covers, resAt, meta, rasters: [Znear, Zfar] };
  }

  const api = { loadBrowser, loadNode, create, decodeHeights };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.MoonTerrain = api;
})(this);
